from itertools import combinations

def find_partitions(k):
    """Find ways to partition [k, k+13] into rows, cols, diags"""
    values = list(range(k, k+14))
    total = sum(values)

    # Need rows sum to 666, cols sum to 666, diags sum to total - 1332
    diag_sum = total - 1332

    valid = []
    for rows in combinations(values, 6):
        if sum(rows) != 666:
            continue
        remaining = [v for v in values if v not in rows]
        for cols in combinations(remaining, 6):
            if sum(cols) != 666:
                continue
            diags = tuple(sorted([v for v in remaining if v not in cols]))
            if len(diags) == 2 and sum(diags) == diag_sum:
                valid.append((rows, cols, diags))
    return valid

for k in range(98, 112):
    parts = find_partitions(k)
    if parts:
        print(f"k={k}: {len(parts)} partitions")
        for p in parts[:3]:
            print(f"  rows={p[0]}, cols={p[1]}, diags={p[2]}")
